async function loadDashboard(){const data=await api('/api/dashboard'),trainerMode=data.kind==='TRAINER';$('#trainerDashboard').hidden=!trainerMode;$('#traineeDashboard').hidden=trainerMode;if(trainerMode){state.trainerClients=data.clients||[];if(!state.trainerClients.some(item=>item.id===state.selectedTraineeId))state.selectedTraineeId=state.trainerClients[0]?.id||null;$('#activeClients').textContent=data.activeClients;$('#workoutsCompleted').textContent=data.workoutsCompleted;$('#completionRate').textContent=`${data.completionRate}%`;$('#progressUpdates').textContent=data.progressUpdates;$('#navClientCount').textContent=data.activeClients;$('#trainerDashboard .stat-grid article:nth-child(1) small').textContent='Active coaching relationships';$('#trainerDashboard .stat-grid article:nth-child(2) small').textContent=`${data.workoutsCompleted} completed total`;$('#trainerDashboard .stat-grid article:nth-child(3) small').textContent=`${data.workoutsCompleted} of ${data.assignedCount} assigned`;$('#trainerDashboard .stat-grid article:nth-child(4) small').textContent='Logged in the last 7 days';$('#trainerDashboard .welcome-row h1').innerHTML=`Good morning, ${escapeText(state.user.name.split(' ')[0])}`;$('#trainerDashboard .welcome-row .eyebrow').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}).toUpperCase();const picker=$('#clientPicker');picker.innerHTML=state.trainerClients.length?state.trainerClients.map(client=>`<option value="${client.id}" ${client.id===state.selectedTraineeId?'selected':''}>${escapeText(client.name)}</option>`).join(''):'<option value="">No active clients</option>';picker.disabled=!state.trainerClients.length;$('#dashboardClientRows').innerHTML=state.trainerClients.length?state.trainerClients.map(client=>`<tr><td><div class="client-cell"><span class="client-avatar lavender">${initials(client.name)}</span><span><strong>${escapeText(client.name)}</strong><small>${escapeText(client.email)}</small></span></div></td><td>${escapeText(client.lastWorkout)}</td><td><div class="mini-progress"><span><i data-w="${client.completionRate}"></i></span><b>${client.completedCount}/${client.assignedCount}</b></div></td><td>${client.assignedCount?'Program active':'No activity'}</td><td><span class="status ${client.completionRate<50?'attention':'active'}">${client.completionRate<50?'Needs check-in':'On track'}</span></td><td><button class="more" data-select-client="${client.id}" aria-label="Select ${escapeText(client.name)}">•••</button></td></tr>`).join(''):'<tr><td colspan="6">No active clients yet. Send an invitation to begin.</td></tr>';$('#clientGrid').innerHTML=state.trainerClients.length?state.trainerClients.map(client=>`<article class="client-profile"><div class="client-avatar lavender">${initials(client.name)}</div><div><h3>${escapeText(client.name)}</h3><p>${escapeText(client.lastWorkout)}</p></div><span class="status ${client.completionRate<50?'attention':'active'}">${client.completionRate<50?'Check-in due':'On track'}</span><div class="client-stats"><span><b>${client.completionRate}%</b>completion</span><span><b>${client.assignedCount}</b>assigned workouts</span></div><button class="secondary-button" data-open-client="${client.id}">Open client</button></article>`).join(''):'<article class="panel empty-state"><h2>No clients connected</h2><p>Invite your first client to begin coaching in Ptrainer.</p><button class="primary-button" data-open-invite>Invite client</button></article>';$$('[data-select-client],[data-open-client]').forEach(button=>button.addEventListener('click',()=>{state.selectedTraineeId=button.dataset.selectClient||button.dataset.openClient;picker.value=state.selectedTraineeId;switchView(button.dataset.openClient?'progress':'dashboard');showToast('Active client updated')}));const schedule=$('.schedule-list');schedule.innerHTML=data.upcoming?.length?data.upcoming.map(item=>`<div class="schedule-item"><div class="time"><strong>${formatDate(item.dueDate)}</strong></div><div class="color-line purple"></div><div class="client-avatar lavender">${initials(item.trainee.name)}</div><div class="schedule-info"><strong>${escapeText(item.trainee.name)}</strong><span>${escapeText(item.name)}</span></div><span class="status upcoming">${escapeText(item.status.toLowerCase())}</span></div>`).join(''):'<div class="template-item"><span>No upcoming workouts.</span></div>';$('.schedule-panel .panel-header p').textContent=`${data.upcoming?.length||0} upcoming workouts`;const next=data.upcoming?.[0],focus=$('.focus-card');focus.querySelector('h2').textContent=next?`${next.name} is next for ${next.trainee.name}`:'Your coaching queue is clear';focus.querySelector('p').textContent=next?`Due ${formatDate(next.dueDate)} · ${next.status.toLowerCase()}. Open the plan or add context while it is relevant.`:'Invite a client or assign a workout to create the next coaching action.';focus.querySelector('.session-readout span').textContent=`${data.completionRate}%`;focus.querySelector('.focus-metric small').textContent=`${data.workoutsCompleted} of ${data.assignedCount} completed`;const attention=$('.attention-list');attention.innerHTML=data.attentionItems?.length?data.attentionItems.map(item=>`<button class="attention-item"><span class="attention-icon warning">!</span><span><strong>Overdue workout</strong><small>${escapeText(item.trainee.name)} · ${escapeText(item.name)} · ${formatDate(item.dueDate)}</small></span><span>›</span></button>`).join(''):'<div class="template-item"><span>No overdue workouts.</span></div>';$('.attention-panel .panel-header p').textContent=`${data.attentionCount} items to review`}else{$('#traineeStreak').textContent=data.currentStreak;$('#traineeCompletion').textContent=`${data.weeklyCompletion}%`;$('.coach-chip').textContent=data.trainerName?`Coach: ${data.trainerName}`:'No trainer connected';if(data.todayWorkout){$('#traineeWorkoutName').textContent=data.todayWorkout.name;$('#traineeWorkoutMeta').textContent=`${data.todayWorkout.exerciseCount} exercises · Status: ${data.todayWorkout.status.toLowerCase()}`;state.activeAssignmentId=data.todayWorkout.id}else{$('#traineeWorkoutName').textContent='No workout assigned';$('#traineeWorkoutMeta').textContent='Your trainer’s next assignment will appear here.'}}}

$('#clientPicker').addEventListener('change',event=>{state.selectedTraineeId=event.target.value||null;const current=$('.page.active-view')?.id?.replace('-view','');if(['progress','nutrition','messages','builder','workouts'].includes(current))switchView(current);loadNotes();showToast('Active client updated')});

const dialog=$('#inviteDialog'),inviteForm=$('#inviteForm'),inviteError=$('#inviteError');const openInvite=()=>{inviteError.textContent='';inviteForm.reset();dialog.showModal()};$('#inviteButton').addEventListener('click',openInvite);$$('[data-open-invite]').forEach(button=>button.addEventListener('click',openInvite));[...dialog.querySelectorAll('[data-close-dialog], .modal-close')].forEach(button=>button.addEventListener('click',()=>dialog.close()));
$('#clientGrid').addEventListener('click',event=>{if(event.target.closest('[data-open-invite]'))openInvite()});
inviteForm.addEventListener('submit',async event=>{event.preventDefault();const fields=new FormData(inviteForm),submit=inviteForm.querySelector('[type="submit"]');inviteError.textContent='';setBusy(submit,true,'Sending…');try{const result=await api('/api/invitations',{method:'POST',body:JSON.stringify({email:fields.get('email'),note:fields.get('note')})});dialog.close();showToast(`Invite created · Code: ${result.invitation.inviteCode}`,9000)}catch(error){inviteError.textContent=error.message}finally{setBusy(submit,false)}});
$('#acceptInviteForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),code=new FormData(form).get('code').trim();$('#acceptInviteError').textContent='';setBusy(button,true,'Connecting…');try{await api(`/api/invitations/${encodeURIComponent(code)}/accept`,{method:'POST',body:'{}'});form.reset();showToast('Trainer connected successfully');await loadDashboard()}catch(error){$('#acceptInviteError').textContent=error.message}finally{setBusy(button,false)}});

function selectedClient(){return state.trainerClients.find(item=>item.id===state.selectedTraineeId)||state.trainerClients[0]}
function traineeQuery(){const client=selectedClient();return state.user?.role==='TRAINER'&&client?`?traineeId=${encodeURIComponent(client.id)}`:''}
async function loadProgress(){try{const result=await api(`/api/progress-entries${traineeQuery()}`);const entries=result.entries||[],displayUnit=result.displayUnit;
// Every point is plotted in one unit. Mixing a kilogram and a pound on one axis
// as bare numbers drew a trend that was simply wrong.
const chartValue=item=>Number(item.display_value??item.value),values=entries.map(chartValue);renderProgressEntries(entries,displayUnit);if(!values.length){$('#progressChart').innerHTML='<div class="template-item"><span>No progress entries yet.</span></div>';$('#progressLatest').textContent='—';return}const min=Math.min(...values),max=Math.max(...values),range=Math.max(1,max-min),unitLabel=displayUnit||entries.at(-1).unit;$('#progressLatest').textContent=`${values.at(-1).toFixed(1)} ${unitLabel}`;$('#progressChart').innerHTML=entries.map(item=>{const height=20+((chartValue(item)-min)/range)*75;return `<div class="chart-point" title="${chartValue(item).toFixed(1)} ${escapeText(unitLabel)}"><i data-h="${height}"></i><small>${new Date(item.measured_at).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</small></div>`}).join('')}catch(error){$('#progressError').textContent=error.message}}
$('#progressForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,fields=new FormData(form),button=form.querySelector('button');$('#progressError').textContent='';setBusy(button,true,'Saving…');try{await api('/api/progress-entries',{method:'POST',body:JSON.stringify({traineeId:state.user.role==='TRAINER'?selectedClient()?.id:undefined,metricType:fields.get('metricType'),value:fields.get('value'),unit:fields.get('unit'),measuredAt:new Date().toISOString()})});form.reset();showToast('Progress entry saved');await loadProgress()}catch(error){$('#progressError').textContent=error.message}finally{setBusy(button,false)}});

const localDate=()=>{const now=new Date(),offset=now.getTimezoneOffset()*60000;return new Date(now-offset).toISOString().slice(0,10)};
const nutritionFields=form=>{const fields=new FormData(form);return{traineeId:state.user.role==='TRAINER'?selectedClient()?.id:undefined,entryDate:fields.get('entryDate'),entryType:fields.get('entryType'),description:fields.get('description'),calories:fields.get('calories'),proteinG:fields.get('proteinG'),carbsG:fields.get('carbsG'),fatG:fields.get('fatG'),waterMl:fields.get('waterMl'),foodBarcode:fields.get('foodBarcode'),foodName:fields.get('foodName'),foodBrand:fields.get('foodBrand'),foodQuantityG:fields.get('foodQuantityG'),dataSource:fields.get('dataSource')}};
function nutritionQuery(){const params=new URLSearchParams(),client=selectedClient(),date=$('#nutritionDateFilter').value;if(state.user?.role==='TRAINER'&&client)params.set('traineeId',client.id);if(date)params.set('date',date);return`?${params}`}
function clearScannedFood({clearMacros=true}={}){const form=$('#nutritionForm');state.scannedFood=null;for(const name of ['foodBarcode','foodName','foodBrand','foodQuantityG','dataSource'])form.elements[name].value='';if(clearMacros)for(const name of ['calories','proteinG','carbsG','fatG'])form.elements[name].value='';$('#scannedFood').hidden=true}
function resetNutritionForm(){const form=$('#nutritionForm');form.reset();clearScannedFood();form.elements.entryDate.value=$('#nutritionDateFilter').value||localDate();form.elements.entryId.value='';$('#nutritionFormTitle').textContent='Add nutrition entry';$('#cancelNutritionEdit').hidden=true;form.querySelector('[type="submit"]').textContent='Save entry'}
function macroSummary(key,label,unit,entries,target){const total=entries.reduce((sum,item)=>sum+Number(item[key]||0),0),goal=target?.[key],progress=goal?Math.min(100,Math.round(total/Number(goal)*100)):0;return`<article class="nutrition-summary-card"><span>${label}</span><strong>${Math.round(total*10)/10}<small>${unit}</small></strong><div class="nutrition-goal"><i data-w="${progress}"></i></div><small>${goal?`${progress}% of ${Number(goal)} ${unit}`:'No target set'}</small></article>`}
async function loadNutrition(){try{const result=await api(`/api/nutrition-entries${nutritionQuery()}`),entries=result.entries||[],target=result.target;state.nutritionEntries=entries;$('#nutritionListCaption').textContent=new Date(`${$('#nutritionDateFilter').value}T12:00:00`).toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});$('#nutritionSummary').innerHTML=[macroSummary('calories','Calories','kcal',entries,target),macroSummary('protein_g','Protein','g',entries,target),macroSummary('carbs_g','Carbs','g',entries,target),macroSummary('fat_g','Fat','g',entries,target),macroSummary('water_ml','Water','ml',entries,target)].join('');$('#nutritionList').innerHTML=entries.length?entries.map(item=>`<article class="nutrition-row"><div class="nutrition-entry-copy"><span class="nutrition-meal-type">${escapeText(item.entry_type.replaceAll('_',' '))}${item.food_barcode?' · SCANNED FOOD':''}</span><strong>${escapeText(item.description||'Nutrition entry')}</strong><small>${item.food_barcode?`${escapeText(item.food_brand||'Packaged food')} · ${Number(item.food_quantity_g||0)} g/ml · `:''}Added by ${escapeText(item.author_name)}</small></div><span>${item.calories??'—'}<small>kcal</small></span><span>${item.protein_g??'—'}<small>protein g</small></span><span>${item.carbs_g??'—'}<small>carbs g</small></span><span>${item.fat_g??'—'}<small>fat g</small></span><span>${item.water_ml??'—'}<small>water ml</small></span>${item.can_manage?`<div class="nutrition-row-actions"><button class="icon-button" type="button" data-edit-nutrition="${item.id}" aria-label="Edit nutrition entry">✎</button><button class="icon-button danger-icon" type="button" data-delete-nutrition="${item.id}" aria-label="Delete nutrition entry">×</button></div>`:''}</article>`).join(''):'<div class="empty-state compact"><h2>No entries for this day</h2><p>Add a meal, daily summary, or water entry.</p></div>';const targetForm=$('#nutritionTargetForm');for(const [name,key]of [['calories','calories'],['proteinG','protein_g'],['carbsG','carbs_g'],['fatG','fat_g'],['waterMl','water_ml']])targetForm.elements[name].value=target?.[key]??''}catch(error){$('#nutritionError').textContent=error.message}}
$('#nutritionDateFilter').value=localDate();resetNutritionForm();
$('#nutritionDateFilter').addEventListener('change',async()=>{resetNutritionForm();await loadNutrition()});
$('#cancelNutritionEdit').addEventListener('click',resetNutritionForm);
$('#nutritionForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,entryId=form.elements.entryId.value,button=form.querySelector('[type="submit"]');$('#nutritionError').textContent='';setBusy(button,true,'Saving…');try{await api(entryId?`/api/nutrition-entries/${encodeURIComponent(entryId)}`:'/api/nutrition-entries',{method:entryId?'PATCH':'POST',body:JSON.stringify(nutritionFields(form))});resetNutritionForm();showToast(entryId?'Nutrition entry updated':'Nutrition entry saved');await loadNutrition()}catch(error){$('#nutritionError').textContent=error.message}finally{setBusy(button,false)}});
$('#nutritionList').addEventListener('click',async event=>{const editButton=event.target.closest('[data-edit-nutrition]'),deleteButton=event.target.closest('[data-delete-nutrition]');if(editButton){const entry=state.nutritionEntries.find(item=>item.id===editButton.dataset.editNutrition),form=$('#nutritionForm');if(!entry)return;resetNutritionForm();form.elements.entryId.value=entry.id;form.elements.entryDate.value=String(entry.entry_date).slice(0,10);form.elements.entryType.value=entry.entry_type;form.elements.description.value=entry.description;for(const [name,key]of [['calories','calories'],['proteinG','protein_g'],['carbsG','carbs_g'],['fatG','fat_g'],['waterMl','water_ml'],['foodBarcode','food_barcode'],['foodName','food_name'],['foodBrand','food_brand'],['foodQuantityG','food_quantity_g'],['dataSource','data_source']])form.elements[name].value=entry[key]??'';if(entry.food_barcode){$('#scannedFood').hidden=false;$('#scannedFoodName').textContent=entry.food_name||'Packaged food';$('#scannedFoodDetails').textContent=`${entry.food_brand||'Unknown brand'} · barcode ${entry.food_barcode}`;}$('#nutritionFormTitle').textContent='Edit nutrition entry';$('#cancelNutritionEdit').hidden=false;form.querySelector('[type="submit"]').textContent='Update entry';form.scrollIntoView({behavior:'smooth',block:'start'})}if(deleteButton){const entry=state.nutritionEntries.find(item=>item.id===deleteButton.dataset.deleteNutrition);if(!entry||!confirm('Delete this nutrition entry? This cannot be undone.'))return;try{await api(`/api/nutrition-entries/${encodeURIComponent(entry.id)}`,{method:'DELETE',body:JSON.stringify({traineeId:state.user.role==='TRAINER'?selectedClient()?.id:undefined})});showToast('Nutrition entry deleted');await loadNutrition()}catch(error){$('#nutritionError').textContent=error.message}}});
$('#nutritionTargetForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,fields=new FormData(form),button=form.querySelector('button');$('#nutritionTargetError').textContent='';setBusy(button,true,'Saving…');try{await api('/api/nutrition-target',{method:'PATCH',body:JSON.stringify({traineeId:state.user.role==='TRAINER'?selectedClient()?.id:undefined,calories:fields.get('calories'),proteinG:fields.get('proteinG'),carbsG:fields.get('carbsG'),fatG:fields.get('fatG'),waterMl:fields.get('waterMl')})});showToast('Daily nutrition targets saved');await loadNutrition()}catch(error){$('#nutritionTargetError').textContent=error.message}finally{setBusy(button,false)}});

const barcodeDialog=$('#barcodeDialog'),barcodeVideo=$('#barcodeVideo');let barcodeStream=null,barcodeFrame=null,barcodeDetecting=false;
function stopBarcodeCamera(){if(barcodeFrame)cancelAnimationFrame(barcodeFrame);barcodeFrame=null;barcodeDetecting=false;if(barcodeStream)barcodeStream.getTracks().forEach(track=>track.stop());barcodeStream=null;barcodeVideo.srcObject=null;$('#barcodeCamera').hidden=true;$('#startBarcodeCamera').textContent='Start camera scanner'}
function updateScannedFoodNutrition(){const product=state.scannedFood;if(!product)return;const form=$('#nutritionForm'),quantity=Number(form.elements.foodQuantityG.value),factor=Number.isFinite(quantity)&&quantity>0?quantity/100:0,nutrients=product.nutritionPer100g;form.elements.calories.value=nutrients.calories==null?'':Math.round(nutrients.calories*factor);for(const [name,key]of [['proteinG','proteinG'],['carbsG','carbsG'],['fatG','fatG']])form.elements[name].value=nutrients[key]==null?'':Math.round(nutrients[key]*factor*10)/10}
function applyScannedFood(product){const form=$('#nutritionForm');state.scannedFood=product;form.elements.foodBarcode.value=product.barcode;form.elements.foodName.value=product.name;form.elements.foodBrand.value=product.brand;form.elements.dataSource.value=product.source;form.elements.foodQuantityG.value=product.suggestedQuantity;form.elements.description.value=[product.name,product.brand].filter(Boolean).join(' · ');$('#scannedFoodName').textContent=product.name;$('#scannedFoodDetails').textContent=`${product.brand||'Unknown brand'} · ${product.servingSize||'nutrition per 100 g/ml'} · barcode ${product.barcode}`;$('#scannedFood').hidden=false;updateScannedFoodNutrition();showToast(`${product.name} added to the nutrition form`)}
async function lookupBarcode(value,button=null){const barcode=String(value||'').replace(/[\s-]/g,'');if(!/^\d{8,14}$/.test(barcode)){$('#barcodeStatus').textContent='Enter an 8–14 digit UPC, EAN, or GTIN barcode.';return}if(button)setBusy(button,true,'Looking up…');$('#barcodeStatus').textContent='Looking up nutrition facts…';stopBarcodeCamera();try{const result=await api(`/api/food-products/${encodeURIComponent(barcode)}`);applyScannedFood(result.product);barcodeDialog.close()}catch(error){$('#barcodeStatus').textContent=error.message}finally{if(button)setBusy(button,false)}}
async function scanBarcodeFrame(detector){if(!barcodeStream||barcodeDetecting)return;barcodeDetecting=true;try{if(barcodeVideo.readyState>=2){const results=await detector.detect(barcodeVideo);if(results[0]?.rawValue){await lookupBarcode(results[0].rawValue);return}}}catch{}finally{barcodeDetecting=false}if(barcodeStream)barcodeFrame=requestAnimationFrame(()=>scanBarcodeFrame(detector))}
async function startBarcodeCamera(){const button=$('#startBarcodeCamera');if(!('BarcodeDetector'in window)||!navigator.mediaDevices?.getUserMedia){$('#barcodeStatus').textContent='Camera scanning is not supported in this browser. Enter the barcode number below.';return}setBusy(button,true,'Opening camera…');try{const supported=BarcodeDetector.getSupportedFormats?await BarcodeDetector.getSupportedFormats():[],preferred=['ean_13','ean_8','upc_a','upc_e','itf'],formats=supported.length?preferred.filter(format=>supported.includes(format)):preferred,detector=new BarcodeDetector(formats.length?{formats}:undefined);barcodeStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}}});barcodeVideo.srcObject=barcodeStream;await barcodeVideo.play();$('#barcodeCamera').hidden=false;button.textContent='Stop camera';button.disabled=false;$('#barcodeStatus').textContent='Hold the barcode inside the guide. Scanning happens automatically.';barcodeFrame=requestAnimationFrame(()=>scanBarcodeFrame(detector))}catch(error){stopBarcodeCamera();$('#barcodeStatus').textContent=error.name==='NotAllowedError'?'Camera permission was denied. Enter the barcode number below.':'The camera could not start. Enter the barcode number below.'}finally{if(!barcodeStream)setBusy(button,false)}}
$('#openBarcodeScanner').addEventListener('click',()=>{stopBarcodeCamera();$('#barcodeLookupForm').reset();$('#barcodeStatus').textContent='Barcode lookups use Open Food Facts. Ptrainer sends the barcode only—never your account or client ID. Always verify the package label.';barcodeDialog.showModal()});
$('#closeBarcodeScanner').addEventListener('click',()=>barcodeDialog.close());barcodeDialog.addEventListener('close',stopBarcodeCamera);
$('#startBarcodeCamera').addEventListener('click',()=>barcodeStream?stopBarcodeCamera():startBarcodeCamera());
$('#barcodeLookupForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;await lookupBarcode(new FormData(form).get('barcode'),form.querySelector('button'))});
$('#nutritionForm [name="foodQuantityG"]').addEventListener('input',updateScannedFoodNutrition);$('#clearScannedFood').addEventListener('click',()=>clearScannedFood());

async function loadMessages(){try{const result=await api(`/api/messages${traineeQuery()}`);$('#messageList').innerHTML=result.messages.length?result.messages.map(item=>`<article class="message-bubble ${item.sender_id===state.user.id?'mine':''}"><strong>${escapeText(item.sender_name)}</strong><p>${escapeText(item.body)}</p><small>${new Date(item.created_at).toLocaleString()}</small></article>`).join(''):'<div class="template-item"><span>No messages yet. Start the coaching conversation.</span></div>';$('#messageList').scrollTop=$('#messageList').scrollHeight}catch(error){$('#messageError').textContent=error.message}}
$('#messageForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),body=new FormData(form).get('body');$('#messageError').textContent='';setBusy(button,true,'Sending…');try{await api('/api/messages',{method:'POST',body:JSON.stringify({body,traineeId:state.user.role==='TRAINER'?selectedClient()?.id:undefined})});form.reset();await loadMessages()}catch(error){$('#messageError').textContent=error.message}finally{setBusy(button,false)}});

const notificationsDialog=$('#notificationsDialog');$('#notificationsButton').addEventListener('click',async()=>{await loadNotifications();notificationsDialog.showModal()});$('[data-close-notifications]').addEventListener('click',()=>notificationsDialog.close());
async function loadNotifications(){if(!state.user)return;try{const result=await api('/api/notifications');$('#notificationDot').hidden=result.unreadCount===0;$('#notificationList').innerHTML=result.notifications.length?result.notifications.map(item=>`<article class="notification-item ${item.read_at?'read':''}" data-notification="${item.id}"><i></i><div><strong>${escapeText(item.title)}</strong><span>${escapeText(item.body)}</span><small>${new Date(item.created_at).toLocaleString()}</small></div></article>`).join(''):'<div class="template-item"><span>You are all caught up.</span></div>';$$('[data-notification]').forEach(item=>item.addEventListener('click',async()=>{await api(`/api/notifications/${item.dataset.notification}/read`,{method:'POST',body:'{}'});item.classList.add('read');await loadNotifications()}))}catch{$('#notificationDot').hidden=true}}

